@mixin global {
	.brumes-story-theme {
		border: none;
		margin: 0;
		padding: 1em 1.5em;
		width: 100%;
		max-width: 16rem;
		background-color: transparent;
		background-position: center;
		background-size: contain;
		background-repeat: no-repeat;
		display: flex;
		flex-direction: column;
		align-items: center;

		&--might-origin {
			aspect-ratio: 1188 / 808;

			.brumes-story-theme--category {
				color: #4d8061;
			}
		}
		&--might-adventure {
			aspect-ratio: 1188 / 793;

			.brumes-story-theme--category {
				color: #7d3c3c;
			}
		}
		&--might-greatness {
			aspect-ratio: 1188 / 796;

			.brumes-story-theme--category {
				color: #5c5c91;
			}
		}
		&--might-standard {
			aspect-ratio: 1188 / 697;

			.brumes-story-theme--category {
				display: none;
			}
		}

		&--category {
			font-family: "IM Fell Great Primer", serif;
			font-variant: small-caps;
			font-weight: bold;
			font-size: 0.85em;
			text-align: center;
		}

		&--title-box {
			font-size: 2em;
			font-family: "IM Fell English", serif;
			font-style: italic;
			width: 100%;
			text-align: center;
		}

		&--title {
			//background: var(--brumes-power-color);
			background: linear-gradient(var(--brumes-power-color) 0 0) 0/100%
				15px no-repeat;
			box-decoration-break: clone;
			border: none;
		}

		&--tags {
			list-style: none;
			padding: 0;
			margin: 0;
			display: flex;
			flex-direction: column;
			align-items: center;
			gap: 0.25em;
			text-align: center;
		}
	}

	.brumes-story-theme {
		background-image: url(data:image/png;base64,);
	}

	.brumes-story-theme--might-origin {
		background-image: url(data:image/png;base64,);
	}

	.brumes-story-theme--might-adventure {
		background-image: url(data:image/png;base64,);
	}

	.brumes-story-theme--might-greatness {
		background-image: url(data:image/png;base64,);
	}
}
